<template>
  <div class="app-stage" :style="themeVars" @pointermove="trackPointer" @pointerdown="createRipple">
    <TopProgressBar/>
    <InteractiveShellBackground :accent="accent.hex" :intensity="backgroundIntensity" />
    <div class="cursor-aura" :class="{visible:cursor.visible}" :style="{transform:`translate3d(${cursor.x}px,${cursor.y}px,0)`}"/>
    <el-container class="shell">
      <el-aside :width="collapsed?'82px':'246px'" class="sidebar" :class="{collapsed}">
        <div class="brand" @click="toggleCollapse">
          <div class="brand-orbit"><span></span><el-icon><Calendar/></el-icon></div>
          <transition name="brand-text"><div v-if="!collapsed" class="brand-copy"><b>ATTEND</b><small>智慧考勤中心</small></div></transition>
        </div>
        <div v-if="auth.role==='STUDENT'" class="student-chip" :class="{mini:collapsed}" @click="router.push('/student/profile')">
          <div class="avatar">{{auth.user?.realName?.slice(0,1)}}</div><transition name="brand-text"><div v-if="!collapsed" class="student-copy"><b>{{auth.user?.realName}}</b><span>{{auth.user?.username}} · 学生端</span></div></transition>
        </div>
        <div v-else-if="!collapsed" class="workspace-label">CONTROL CENTER</div>
        <el-menu :default-active="$route.path" router :collapse="collapsed" :collapse-transition="false">
          <el-menu-item v-for="(item,index) in menus" :key="item.path" :index="'/'+item.path" :style="{'--delay':`${index*35}ms`}">
            <div class="menu-icon"><el-icon><component :is="item.icon"/></el-icon></div><template #title><span>{{item.title}}</span></template><i class="active-beam"></i>
          </el-menu-item>
        </el-menu>
        <div class="sidebar-footer"><div class="signal"><i></i><span v-if="!collapsed">系统在线</span></div><button class="collapse-control" @click="toggleCollapse"><el-icon :class="{reverse:collapsed}"><DArrowLeft/></el-icon></button></div>
      </el-aside>

      <el-container class="right-stage">
        <el-header class="header">
          <div class="header-left"><button class="mobile-toggle" @click="toggleCollapse"><el-icon><Fold/></el-icon></button><div class="route-mark"><span>0{{ Math.max(1,menus.findIndex(x=>'/'+x.path===$route.path)+1) }}</span></div><div><el-breadcrumb separator="·"><el-breadcrumb-item>{{auth.role==='STUDENT'?'学生空间':'管理中心'}}</el-breadcrumb-item><el-breadcrumb-item>{{displayTitle}}</el-breadcrumb-item></el-breadcrumb><small class="route-subtitle">{{routeSubtitle}}</small></div></div>
          <div class="header-actions">
            <div class="live-clock"><span>{{clock.date}}</span><b>{{clock.time}}</b></div>
            <el-popover placement="bottom" :width="190" trigger="click"><template #reference><button class="round-action" title="切换视觉主题"><el-icon><MagicStick/></el-icon></button></template><div class="theme-panel"><b>视觉能量</b><span>选择你的界面光谱</span><div><button v-for="option in accents" :key="option.name" :class="{selected:accent.name===option.name}" :style="{background:option.hex}" @click="setAccent(option)"></button></div></div></el-popover>
            <button class="round-action" title="全屏" @click="toggleFullscreen"><el-icon><FullScreen/></el-icon></button>
            <button v-if="auth.role==='STUDENT'" class="round-action has-dot" title="通知中心" @click="router.push('/student/notifications')"><el-icon><Bell/></el-icon></button>
            <el-dropdown><button class="account-pill"><span class="account-avatar">{{auth.user?.realName?.slice(0,1)}}</span><span class="account-copy"><b>{{auth.user?.realName}}</b><small>{{roleName}}</small></span><el-icon><ArrowDown/></el-icon></button><template #dropdown><el-dropdown-menu><el-dropdown-item v-if="auth.role==='STUDENT'" @click="router.push('/student/profile')">个人中心</el-dropdown-item><el-dropdown-item divided @click="logout">退出登录</el-dropdown-item></el-dropdown-menu></template></el-dropdown>
          </div>
        </el-header>
        <el-main ref="mainRef" class="content-main" @scroll="onScroll">
          <router-view v-slot="{Component,route}"><transition name="page-shift" mode="out-in"><component :is="Component" :key="route.path"/></transition></router-view>
        </el-main>
      </el-container>
    </el-container>
    <transition name="back-top"><button v-if="showBackTop" class="back-top" title="返回顶部" @click="scrollToTop"><el-icon><ArrowUpBold/></el-icon></button></transition>
  </div>
