<script setup>
import{computed,onBeforeUnmount,onMounted,reactive,ref}from'vue'
import{useRoute,useRouter}from'vue-router'
import{useAuthStore}from'../stores/auth'
import InteractiveShellBackground from'../components/InteractiveShellBackground.vue'
import TopProgressBar from'../components/TopProgressBar.vue'

const auth=useAuthStore(),router=useRouter(),route=useRoute(),mainRef=ref()
const collapsed=ref(localStorage.getItem('attendance_sidebar_collapsed')==='1'),cursor=reactive({x:0,y:0,visible:false}),clock=reactive({date:'',time:''}),showBackTop=ref(false)
const accents=[{name:'electric',hex:'#4f7cff',rgb:'79,124,255'},{name:'violet',hex:'#8b5cf6',rgb:'139,92,246'},{name:'cyan',hex:'#06a7c9',rgb:'6,167,201'},{name:'rose',hex:'#e64980',rgb:'230,73,128'}]
const savedAccent=localStorage.getItem('attendance_accent'),accent=ref(accents.find(x=>x.name===savedAccent)||accents[0])
const themeVars=computed(()=>({'--accent':accent.value.hex,'--accent-rgb':accent.value.rgb,'--accent-soft':`rgba(${accent.value.rgb},.2)`}))
const all=[['dashboard','首页 Dashboard','HomeFilled',['STUDENT']],['my/attendance','我的考勤','Calendar',['STUDENT']],['leave/apply','请假申请','DocumentAdd',['STUDENT']],['student/schedule','课程 / 今日安排','Notebook',['STUDENT']],['student/notifications','通知中心','Bell',['STUDENT']],['student/profile','个人中心','UserFilled',['STUDENT']],['dashboard','数据看板','DataAnalysis',['ADMIN','TEACHER']],['users','账号管理','UserFilled',['ADMIN']],['students','学生管理','User',['ADMIN']],['teachers','教师管理','Avatar',['ADMIN']],['classes','班级管理','School',['ADMIN']],['courses','课程管理','Reading',['ADMIN']],['teaching','课程安排','Notebook',['ADMIN','TEACHER']],['attendance/tasks','考勤任务','Checked',['ADMIN','TEACHER']],['attendance/records','异常考勤记录','List',['ADMIN','TEACHER']],['leave/approval','请假审批','DocumentChecked',['ADMIN','TEACHER']]]
const menus=computed(()=>all.filter(item=>item[3].includes(auth.role)).map(item=>({path:item[0],title:item[1],icon:item[2]}))),roleName=computed(()=>({ADMIN:'管理员',TEACHER:'教师',STUDENT:'学生'}[auth.role]))
const subtitles={'数据看板':'洞察实时出勤数据','首页 Dashboard':'今天也要保持好状态','学生管理':'管理学生档案与班级归属','教师管理':'维护师资与教学关系','班级管理':'组织班级基础资料','课程管理':'构建课程与学期计划','课程安排':'连接课程、班级与教师','考勤任务':'发起并控制课堂考勤','考勤录入':'快速标记学生出勤状态','异常考勤记录':'聚焦需要处理的异常','请假审批':'及时处理学生请假申请','我的考勤':'每一次出勤都清晰可见','请假申请':'提交并追踪审批进度','课程 / 今日安排':'掌握今天的每一节课','通知中心':'重要动态，一处掌握','个人中心':'管理你的资料与账号安全'}
const displayTitle=computed(()=>route.path==='/dashboard'&&auth.role==='STUDENT'?'首页 Dashboard':route.meta.title)
const routeSubtitle=computed(()=>subtitles[displayTitle.value]||'智慧校园 · 高效协同')
const backgroundIntensity=computed(()=>route.path==='/dashboard'?'full':'subtle')
let clockTimer
function updateClock(){const now=new Date();clock.date=new Intl.DateTimeFormat('zh-CN',{month:'2-digit',day:'2-digit',weekday:'short'}).format(now);clock.time=now.toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:false})}
function toggleCollapse(){collapsed.value=!collapsed.value;localStorage.setItem('attendance_sidebar_collapsed',collapsed.value?'1':'0')}
function setAccent(option){accent.value=option;localStorage.setItem('attendance_accent',option.name)}
function toggleFullscreen(){if(!document.fullscreenElement)document.documentElement.requestFullscreen?.();else document.exitFullscreen?.()}
function trackPointer(event){cursor.x=event.clientX-110;cursor.y=event.clientY-110;cursor.visible=true;const card=event.target.closest?.('.page-card');if(!card)return;const rect=card.getBoundingClientRect();card.style.setProperty('--pointer-x',`${((event.clientX-rect.left)/rect.width)*100}%`);card.style.setProperty('--pointer-y',`${((event.clientY-rect.top)/rect.height)*100}%`)}
function createRipple(event){const button=event.target.closest?.('.el-button,.round-action,.account-pill,.collapse-control');if(!button||window.matchMedia('(prefers-reduced-motion: reduce)').matches)return;const rect=button.getBoundingClientRect(),ripple=document.createElement('i');ripple.className='ui-ripple';ripple.style.left=`${event.clientX-rect.left}px`;ripple.style.top=`${event.clientY-rect.top}px`;button.appendChild(ripple);setTimeout(()=>ripple.remove(),700)}
function onScroll(event){showBackTop.value=event.target.scrollTop>420}
function scrollToTop(){mainRef.value?.$el?.scrollTo?.({top:0,behavior:'smooth'})}
async function logout(){await auth.logout();router.push('/login')}
onMounted(()=>{updateClock();clockTimer=setInterval(updateClock,1000);if(window.innerWidth<760)collapsed.value=true})
onBeforeUnmount(()=>clearInterval(clockTimer))
</script>

