n:transform .35s}.collapse-control .reverse{transform:rotate(180deg)}.right-stage{min-width:0;background:transparent}.header{position:relative;height:78px;margin:12px 14px 0 14px;padding:0 18px 0 15px;display:flex;align-items:center;justify-content:space-between;border:1px solid rgba(255,255,255,.75);border-radius:20px;background:rgba(255,255,255,.67);backdrop-filter:blur(24px) saturate(150%);box-shadow:0 12px 35px rgba(31,63,111,.09)}.header-left,.header-actions{display:flex;align-items:center}.header-left{gap:12px}.header-actions{gap:9px}.mobile-toggle{display:none;width:38px;height:38px;border-radius:11px;background:#edf3ff;color:var(--accent)}.route-mark{width:40px;height:40px;display:grid;place-items:center;border:1px solid rgba(var(--accent-rgb),.13);border-radius:12px;background:rgba(var(--accent-rgb),.07);color:var(--accent);font-size:12px;font-weight:800}.header :deep(.el-breadcrumb__inner){font-size:13px;color:#44516a}.header :deep(.el-breadcrumb__item:last-child .el-breadcrumb__inner){font-weight:700;color:#1d2c46}.route-subtitle{display:block;margin-top:5px;color:#95a0b3;font-size:10px;letter-spacing:.4px}.live-clock{padding-right:12px;display:flex;flex-direction:column;align-items:flex-end;border-right:1px solid #e5eaf2}.live-clock span{color:#8a96a8;font-size:10px}.live-clock b{margin-top:2px;color:#31415b;font-size:13px;font-variant-numeric:tabular-nums}.round-action{position:relative;width:40px;height:40px;display:grid;place-items:center;overflow:hidden;border:1px solid rgba(31,55,90,.07);border-radius:13px;background:rgba(255,255,255,.75);color:#526079;font-size:17px;transition:.25s}.round-action:hover{color:var(--accent);transform:translateY(-2px);box-shadow:0 8px 20px rgba(var(--accent-rgb),.15)}.has-dot:after{content:'';position:absolute;width:7px;height:7px;right:8px;top:7px;border:2px solid #fff;border-radius:50%;background:#ff536b}.account-pill{position:relative;height:46px;padding:4px 10px 4px 5px;display:flex;align-items:center;gap:9px;overflow:hidden;border-radius:14px;background:rgba(255,255,255,.8);color:#344057;transition:.25s}.account-pill:hover{box-shadow:0 8px 24px rgba(31,63,111,.12);transform:translateY(-1px)}.account-avatar{width:36px;height:36px;border-radius:11px}.account-copy{display:flex;min-width:67px;flex-direction:column;align-items:flex-start}.account-copy b{font-size:12px}.account-copy small{margin-top:2px;color:#9aa5b5;font-size:10px}.content-main{position:relative;padding:0;overflow:auto;scroll-behavior:smooth}.cursor-aura{position:fixed;z-index:2;left:0;top:0;width:220px;height:220px;border-radius:50%;pointer-events:none;opacity:0;background:radial-gradient(circle,rgba(var(--accent-rgb),.1),transparent 68%);transition:opacity .3s;will-change:transform}.cursor-aura.visible{opacity:1}.theme-panel>b,.theme-panel>span{display:block}.theme-panel>span{margin:5px 0 14px;color:#909bad;font-size:11px}.theme-panel>div{display:flex;gap:11px}.theme-panel button{width:28px;height:28px;border:3px solid #fff;border-radius:9px;box-shadow:0 3px 10px #ccd4e2;cursor:pointer;transition:.2s}.theme-panel button:hover,.theme-panel button.selected{transform:scale(1.17) rotate(5deg);box-shadow:0 0 0 2px currentColor}.page-shift-enter-active,.page-shift-leave-active{transition:opacity .22s,transform .35s cubic-bezier(.22,1,.36,1),filter .25s}.page-shift-enter-from{opacity:0;transform:translateY(16px) scale(.992);filter:blur(4px)}.page-shift-leave-to{opacity:0;transform:translateY(-8px);filter:blur(3px)}.brand-text-enter-active,.brand-text-leave-active{transition:.25s}.brand-text-enter-from,.brand-text-leave-to{opacity:0;transform:translateX(-10px)}@keyframes orbit{to{transform:rotate(360deg)}}@keyframes pulse{50%{box-shadow:0 0 0 9px rgba(56,217,150,0)}}@keyframes menu-enter{from{opacity:0;transform:translateX(-12px)}to{opacity:1;transform:none}}
